/*
 * SH-5 SHcompact ISA test kit: common definitions.
 *
 * Every test calls a small SHcompact routine (cops.S, generated by
 * gen_cops.py) through cop_call() and compares the registers it returns with
 * a C reference written from the pseudocode in SH-5 CPU Core Volume 3
 * (SHcompact). The same sources build as an SHmedia program with SHcompact
 * routines for the SH-5 (MODE=sh5: RTL model, qemu-system-sh5 -M cayman) and
 * as a pure SHcompact program for an SH-4 (MODE=sh4: qemu-system-sh4 -M r2d),
 * where the routines are plain SH-4 code and the references can be checked
 * against a mature implementation.
 */
#ifndef ISA_HARNESS_H
#define ISA_HARNESS_H

typedef unsigned long long u64;
typedef long long s64;
typedef unsigned int u32;
typedef int s32;
typedef unsigned short u16;
typedef short s16;
typedef unsigned char u8;
typedef signed char s8;

/*
 * Output layer (bare_sh5.c / bare_sh4.c). No function of the kit takes or
 * returns a 64-bit scalar: for such calls the SHcompact code generator uses
 * libgcc trampolines that are SHmedia code, which the SH-4 build cannot run.
 * The SH-4 build also links without libgcc, so the groups avoid division
 * (isa_udiv32) and 64-bit shifts by variable amounts.
 */
void isa_puts(const char *s);
void isa_puthex(const u64 *v);	/* 16 hex digits */
void isa_putdec(u32 v);
void isa_exit(int failures);	/* print DONE, then idle */
u32 isa_udiv32(u32 a, u32 b);

/* Result accounting. */
extern unsigned isa_tests, isa_failures, isa_group_failures;
extern int isa_verbose;

void isa_group_begin(const char *name);
void isa_group_end(void);

struct isa_chk {
	const char *file, *insn;
	int line, nops;
	u64 got, want, a, b, c;
};
int isa_check(const struct isa_chk *k);

#define ISA_CHK(insn, got, want, n, a, b, c) ({				\
	struct isa_chk _k = { __FILE__, insn, __LINE__, n, (got), (want), (a), (b), (c) }; \
	isa_check(&_k); })
#define CHECK0(insn, got, want)          ISA_CHK(insn, got, want, 0, 0, 0, 0)
#define CHECK1(insn, got, want, a)       ISA_CHK(insn, got, want, 1, a, 0, 0)
#define CHECK2(insn, got, want, a, b)    ISA_CHK(insn, got, want, 2, a, b, 0)
#define CHECK3(insn, got, want, a, b, c) ISA_CHK(insn, got, want, 3, a, b, c)

/* 64-bit boundary values (used by the SH-5 only tests) */
extern const u64 isa_operands[];
extern const unsigned isa_num_operands;
#define ISA_FOREACH_OPERAND(v) \
	for (unsigned _i_##v = 0; _i_##v < isa_num_operands && (((v) = isa_operands[_i_##v]), 1); _i_##v++)

/* 32-bit boundary values: the corpus of the SHcompact tests */
extern const u32 cop_operands[];
extern const unsigned cop_num_operands;
#define COP_FOREACH(v) \
	for (unsigned _i_##v = 0; _i_##v < cop_num_operands && (((v) = cop_operands[_i_##v]), 1); _i_##v++)

u32 isa_rand(void);
void isa_rand_seed(u32 seed);

static inline s64 SignExtend8(u64 v)  { return (s64)(s8)v; }
static inline s64 SignExtend16(u64 v) { return (s64)(s16)v; }
static inline s64 SignExtend32(u64 v) { return (s64)(s32)v; }
static inline u64 ZeroExtend8(u64 v)  { return (u8)v; }
static inline u64 ZeroExtend16(u64 v) { return (u16)v; }
static inline u64 ZeroExtend32(u64 v) { return (u32)v; }

struct isa_group {
	const char *name;
	void (*run)(void);
};

#define ISA_GROUP(gname)						\
	static void isa_group_fn_##gname(void);				\
	static const struct isa_group isa_group_desc_##gname		\
	__attribute__((section("isa_groups"), used, aligned(8))) =	\
		{ #gname, isa_group_fn_##gname };			\
	static void isa_group_fn_##gname(void)

/*
 * Calling an SHcompact routine. The routine receives a, b, c, d in R4-R7
 * (32-bit sign-extended values on the SH-5), returns R0-R3 in res and comes
 * back with RTS. Most routines put the result register in R0 and the T-bit
 * in R1 (see gen_cops.py). Routines may use R0-R7 freely and must keep
 * R8-R15; on the SH-5 they also clobber R20-R23 and TR0-TR3.
 */
struct cres {
	u64 r0, r1, r2, r3;
};
extern void cop_call(const void *fn, const u64 in[4], struct cres *res);

static inline struct cres cop(const void *fn, u32 a, u32 b, u32 c, u32 d)
{
	u64 in[4] = { (u64)(s64)(s32)a, (u64)(s64)(s32)b, (u64)(s64)(s32)c, (u64)(s64)(s32)d };
	struct cres r;

	cop_call(fn, in, &r);
	return r;
}

/* Address of a buffer as an SHcompact routine must see it (sign-extended). */
#define ADDR(p)	((u32)(unsigned long)(p))

/*
 * Expected register value for a 32-bit result: SHcompact writes the sign
 * extension of bit 31 into the upper half of a general register (Vol. 3
 * Table 2); the SH-4 build only has the low word.
 */
#ifdef ISA_SH4
#define RES32(x)	((u64)(u32)(x))
#else
#define RES32(x)	((u64)(s64)(s32)(x))
#endif

/* Unexpected exceptions during the group (SH-5 build: counted by the vectors). */
extern volatile u64 cop_exc_count, cop_exc_last;

#endif /* ISA_HARNESS_H */
